    ('64ad25a0-6088-470f-a0f0-368159ceb43e'::uuid, 'site_type', 'Megalithic structures', 'Rock relief/carving', 'fields-wd1-2026-09-26d-s010:64ad25a0-6088-470f-a0f0-368159ceb43e:site_type', 'fields-wd1-2026-09-26d-s010 (wd1-replace): ''Megalithic structures'' -> ''Rock relief/carving''', '[{"source": "https://docslib.org/doc/9458304/cart-ruts-and-rock-prehistoric-calendar-at-zonzamas-lanzarote-quesera-cheeseboard", "url": "https://docslib.org/doc/9458304/cart-ruts-and-rock-prehistoric-calendar-at-zonzamas-lanzarote-quesera-cheeseboard", "quote": "DOCSLIB.ORG Sign Up Log In Upload Search Sign Up Log In Upload Cart-Ruts and Rock Prehistoric Calendar at Zonzamas, Lanzarote -\"Quesera\"/Cheeseboard Total Page：", "outcome": "found"}, {"source": "https://www.ilanzarote.com/quesera-de-zonzamas/", "url": "https://www.ilanzarote.com/quesera-de-zonzamas/", "quote": "The structure consists of five channels carved into a block of porous basalt, measuring 3.90 meters in diameter.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0372)", "decision": "replace", "status": "MISSING", "reasoning": "ilanzarote describes five channels carved into a block of porous basalt and the International Journal of Modern Anthropology paper (via Docslib) a rock calendar at Zonzamas; a rock carving, not a megalithic structure.", "value_page": null}]'::jsonb),
    ('64ad25a0-6088-470f-a0f0-368159ceb43e'::uuid, 'source_url', 'https://www.researchgate.net/figure/Quesera-Cheeseboard-of-Zonzamas-Lanzarote_fig1_327546165', 'https://www.ilanzarote.com/quesera-de-zonzamas/', 'fields-wd1-2026-09-26d-s010:64ad25a0-6088-470f-a0f0-368159ceb43e:source_url', 'fields-wd1-2026-09-26d-s010 (wd1-replace): ''https://www.researchgate.net/figure/Quesera-Cheeseboard-of-Zonzamas-Lanzarote_fig1_327546165'' -> ''https://www.ilanzarote.com/quesera-de-zonzamas/''', '[{"source": "https://www.ilanzarote.com/quesera-de-zonzamas/", "url": "https://www.ilanzarote.com/quesera-de-zonzamas/", "quote": "Associated with the Quesera de Zonzamas are engravings of foot silhouettes, known as podomorphs.", "outcome": "found"}, {"source": "https://www.eldiario.es/canariasahora/patrimonio-canarias/mayor-misterio-arqueologia-canarias_1_11752574.html", "url": "https://www.eldiario.es/canariasahora/patrimonio-canarias/mayor-misterio-arqueologia-canarias_1_11752574.html", "quote": "Quesera de Zonzamas, una enigmática estructura construida por los majos, los primeros pobladores de Lanzarote.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0372)", "decision": "replace", "status": "MISSING", "reasoning": "The stored ResearchGate figure cannot be read (HTTP 403); ilanzarote''s page is about the Quesera de Zonzamas, which El Diario names too.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
